using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using Cysharp.Threading.Tasks;using UnityEngine;using UnityEngine.UI;using UnityEditor;using SushiAndFish.Casino;using SushiAndFish.Casino.Original;using SushiAndFish.Casino.Original.CasinoLab;using SushiAndFish.Casino.Original.Extensions;using Object=UnityEngine.Object;
public static partial class CityExpansionPlayAudit {
 [Serializable]public class ShotAudit {public string utc,stage,error;public bool passed;public int menuProxy,menuCompiled;public List<string> notes=new List<string>();public List<ScreenCase> screens=new List<ScreenCase>();}
 [Serializable]public class ScreenCase {public string game,text,error,material,shader;public float hostNear,hostFar,near,far,ortho,size,distance;public Vector3 cam,display,viewport,rawPosition;public int mask,textLayer,opaquePixels,brightPixels;public bool canvas,renderer,orthographic;}
 static ShotAudit shot;static string ShotPath=>Path.Combine(Reports,"screenshot-followup-runtime.json");
 public static void ScreensAndCoast(){SessionState.SetBool(Key+"screenshot",true);SessionState.SetBool(Key+"detailed",false);SessionState.SetBool(Key+"roofCoast",false);SessionState.SetBool(Key+"probe",false);StartMode(false);}
 static void ShotStage(string stage){shot.stage=stage;File.WriteAllText(ShotPath,JsonUtility.ToJson(shot,true));Stage("SCREENSHOT_"+stage);}
 static async UniTask ScreenshotMenu(){shot=new ShotAudit{utc=DateTime.UtcNow.ToString("o")};await Pause(1);foreach(var m in Resources.FindObjectsOfTypeAll<Material>().Where(SushiAndFish.Casino.CasinoShaderOwnership.Owns)){if(m.shader==RecoveryShaderSupport.CompiledFor(m.shader))shot.menuCompiled++;else shot.menuProxy++;}ShotStage("MENU_INSPECTED");}
 static (int,int) PixelCounts(RenderTexture rt){var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);tex.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);tex.Apply();var p=tex.GetPixels32();int opaque=p.Count(c=>c.a>20),bright=p.Count(c=>c.a>20&&c.r+c.g+c.b>210);Object.Destroy(tex);RenderTexture.active=old;return(opaque,bright);}
 static async UniTask ScreenshotRun(ParkCasinoIntegration c){try{
  c.HostEconomy.SetSavedGoldBalance(0,"10000000000",c.HostEconomy.ScrapBalance.Value);
  var e=NetworkSingleton<ElevatorManager>.Instance;var b=CasinoLabBootstrap.Field<List<Transform>>(e,"buttonList")[1].GetComponent<InteractableEventTrigger>();c.HostPlayer.TeleportPlayer(e.playerSpawnPosition.position-Vector3.up*(.4f*c.CurrentScale),true);await Pause(.2f);b.ServerOnInteract(c.LogicInteractor);await Pause(.1f);await Wait(()=>!e.isTeleporting&&c.Bootstrap.ready,30);await Pause(1);
  var host=CasinoRuntimeContext.PlayerCamera;shot.notes.Add("HOST cam "+host.transform.position+" near "+host.nearClipPlane+" far "+host.farClipPlane+" mask "+host.cullingMask+" sky "+RenderSettings.skybox?.name);
  foreach(var pad in c.ModuleRoot.GetComponentsInChildren<Keypad>(false).Where(k=>k.NetworkcasinoGame)){
   var cam=pad.keypadCamera;var text=CasinoLabBootstrap.Field<TMPro.TextMeshPro>(pad,"displayText");var raw=CasinoLabBootstrap.Field<RawImage>(pad,"keypadRenderTarget");var can=raw.GetComponentInParent<Canvas>();pad.SendMessage("RequestRender",SendMessageOptions.DontRequireReceiver);await Pause(.1f);var pix=PixelCounts(cam.targetTexture);
   shot.screens.Add(new ScreenCase{game=pad.NetworkcasinoGame.GameType.ToString(),text=text.text,error=pad.Network_errorMessage,hostNear=host.nearClipPlane,hostFar=host.farClipPlane,near=cam.nearClipPlane,far=cam.farClipPlane,ortho=cam.orthographicSize,orthographic=cam.orthographic,cam=cam.transform.position,display=text.transform.position,viewport=cam.WorldToViewportPoint(text.transform.position),rawPosition=raw.transform.position,mask=cam.cullingMask,textLayer=text.gameObject.layer,canvas=can.enabled,renderer=text.GetComponent<Renderer>().enabled,material=raw.material?.name,shader=raw.material?.shader?.name,opaquePixels=pix.Item1,brightPixels=pix.Item2});
   shot.notes.Add(pad.NetworkcasinoGame.GameType+" canvas mode="+can.renderMode+" camera="+can.worldCamera?.name+" scale="+can.transform.lossyScale+" shader="+text.fontSharedMaterial.shader.name+" rawRect="+raw.rectTransform.rect);
  }
  foreach(var comp in Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).Where(x=>x.GetType().Name.IndexOf("Reflection",StringComparison.OrdinalIgnoreCase)>=0||x.GetType().Name.IndexOf("Underwater",StringComparison.OrdinalIgnoreCase)>=0))shot.notes.Add("ENV "+comp.GetType().FullName+" "+ScreenshotFollowupRepair.P(comp.transform)+" enabled="+comp.enabled);
  shot.passed=true;ShotStage("DIAGNOSED");
 }catch(Exception ex){shot.error=ex.ToString();ShotStage("FAILED");throw;}}
}
